import{XBUDDY_SOURCE}from './xbuddy-service-source.js?v=20261111-94';
const l=s=>s.split('|'),step=(title,body,refs,action,extra={})=>({title:l(title),body:l(body),refs,...(action?{action}:{}),...extra});
export const XBUDDY_TASK={id:'xbuddy',category:2,revision:1,title:l('xBuddyを交換する|Replace the xBuddy|Výměna desky xBuddy|xBuddy austauschen'),interval:l('交換が必要なとき|When replacement is needed|Při potřebě výměny|Bei erforderlichem Austausch'),source:XBUDDY_SOURCE.url,steps:[
step('作業を始める前に|Before starting|Před zahájením|Vor Beginn','CORE One／One+のxBuddy交換手順です。交換用の基板とサーマルパッドを用意します。|Prepare a replacement xBuddy and thermal pads for your CORE One / One+.|Pro CORE One / One+ připravte novou desku xBuddy a teplovodivé podložky.|Ersatz-xBuddy und Wärmeleitpads für CORE One / One+ bereitlegen.',['xBuddy']),
step('工具を用意する|Prepare the tools|Příprava nářadí|Werkzeug vorbereiten','2.5 mm六角レンチ、T10、ラジオペンチ、プラスドライバーを用意します。結束バンドの切断にはニッパーを使います。|Prepare a 2.5 mm Allen key, T10, needle-nose pliers and Phillips screwdriver. Flush cutters help remove cable ties.|Připravte 2,5mm imbus, T10, úzké kleště a křížový šroubovák. Na stahovací pásky jsou vhodné štípací kleště.|2,5-mm-Inbus, T10, Spitzzange und Kreuzschlitzschraubendreher bereitlegen. Für Kabelbinder eignet sich ein Seitenschneider.',['xBuddy']),
step('静電気から基板を守る|Protect against static discharge|Ochrana před statickou elektřinou|Vor statischer Entladung schützen','交換基板は取り付ける直前までESD袋に入れておきます。金属部に触れて静電気を逃がし、基板は縁を持ちます。部品や端子には触れません。|Keep the new board in its ESD bag until installation. Discharge static on a nearby metal structure and hold the board by its edges. Avoid components and contacts.|Novou desku ponechte do montáže v ESD sáčku. Dotykem kovové konstrukce vybijte statický náboj. Desku držte za okraje, ne za součástky nebo kontakty.|Neue Platine bis zur Montage im ESD-Beutel lassen. An einer Metallstruktur entladen und die Platine nur am Rand anfassen. Bauteile und Kontakte nicht berühren.',['xBuddy']),
step('アンロードして冷却する|Unload and cool down|Vysunutí filamentu a ochlazení|Entladen und abkühlen','ドアを閉じ、Filament → Unload filamentでアンロードします。スプールを外し、Preheat → COOLDOWNで室温まで冷却します。|Close the door, unload via Filament → Unload filament and remove the spool. Select Preheat → COOLDOWN and wait for room temperature.|Zavřete dvířka, přes Filament → Unload filament vysuňte filament a odeberte cívku. V Preheat → COOLDOWN nechte tiskárnu vychladnout na pokojovou teplotu.|Tür schließen, Filament über Filament → Unload filament entladen und Spule abnehmen. Mit Preheat → COOLDOWN auf Raumtemperatur abkühlen.',['lcd','hotend']),
step('ベッドを下げて電源を切る|Lower the bed and disconnect power|Spuštění podložky a odpojení|Heizbett absenken und Netzstecker ziehen','Control → Move Axis → Move Zで100 mm以上にします。ベッドの停止後、背面スイッチで電源を切り、電源コードを抜きます。|Use Control → Move Axis → Move Z to set at least 100 mm. Wait for the bed to stop, switch off at the rear and unplug the printer.|V Control → Move Axis → Move Z nastavte alespoň 100 mm. Po zastavení podložky vypněte zadní vypínač a odpojte napájení.|Unter Control → Move Axis → Move Z mindestens 100 mm einstellen. Heizbett anhalten lassen, hinten ausschalten und Netzstecker ziehen.',['bedSupport','heatbed','sheet','psu'],'xb-bed-down'),
step('背面カバーを下へずらす|Release the rear cover|Uvolnění zadního krytu|Rückabdeckung lösen','本体内側から固定ネジ2本を外します。背面カバーを下げ、上側のフック4か所を外します。|Remove the two screws from inside the printer. Slide the rear cover down until all four upper hooks release.|Zevnitř tiskárny vyjměte oba šrouby. Zadní kryt posuňte dolů a uvolněte všechny čtyři horní háčky.|Die beiden Schrauben von innen entfernen. Rückabdeckung nach unten schieben, bis alle vier oberen Haken frei sind.',[78],'xb-rear-release'),
step('背面カバーを取り外す|Remove the rear cover|Sejmutí zadního krytu|Rückabdeckung abnehmen','カバーを少し手前へ引きます。下側を外へ傾け、上側を本体へ寄せながら、裏のケーブル束から外します。|Pull the cover back slightly. Tilt its bottom outward and its top toward the printer to clear the cable bundle behind it.|Kryt mírně odtáhněte dozadu. Spodek vyklopte ven a horní část nakloňte k tiskárně, aby se uvolnil svazek kabelů.|Abdeckung etwas nach hinten ziehen. Unten nach außen und oben zum Drucker kippen, um das Kabelbündel dahinter freizugeben.',[78],'xb-rear-out'),
step('xBuddyカバーを外す|Remove the xBuddy cover|Sejmutí krytu xBuddy|xBuddy-Abdeckung entfernen','固定ネジ6本を外し、カバーを引き出します。外したネジは戻す位置ごとに保管します。|Remove all six screws and slide out the cover. Keep the removed screws for their original positions.|Vyjměte všech šest šroubů a kryt vysuňte. Šrouby uschovejte pro původní pozice.|Alle sechs Schrauben entfernen und Abdeckung herausziehen. Schrauben für ihre ursprünglichen Positionen aufbewahren.',[206],'xb-box-out'),
step('NFCアンテナカバーを外す|Remove the NFC antenna cover|Sejmutí krytu NFC antény|NFC-Antennenabdeckung entfernen','M3×10を2本外します。xBuddyの小さな金色のNFC端子をまっすぐ持ち上げ、ケーブルを外してからカバーを取り外します。|Remove both M3×10 screws. Gently lift the tiny gold NFC plug from xBuddy, then remove the antenna cover.|Vyjměte oba M3×10. Drobný zlatý NFC konektor na xBuddy opatrně zvedněte přímo nahoru a kryt sejměte.|Beide M3×10 entfernen. Den winzigen goldenen NFC-Stecker vorsichtig gerade vom xBuddy abheben und Antennenabdeckung abnehmen.',[240,'xbNfcPlug'],'xb-nfc-out'),
step('上段とメイン配線を外す|Disconnect upper and main cables|Odpojení horních a hlavních kabelů|Obere und Hauptleitungen abstecken','ラッチを押しながら上段のモーター・拡張基板の端子を外します。側面の結束バンドを切り、xLCD、Nextruderメイン、Power Panicも外します。刃を配線に当てません。|Release the latches on the upper motor and extension plugs. Cut the side ties without nicking wires, then unplug xLCD, Nextruder main and Power Panic.|Stiskněte západky horních motorových konektorů a propojení přídavné desky. Bez poškození vodičů odstřihněte boční pásky a odpojte xLCD, Nextruder a Power Panic.|Verriegelungen der oberen Motor- und Erweiterungsstecker lösen. Seitliche Kabelbinder ohne Kabelschaden durchtrennen, dann xLCD, Nextruder und Power Panic abstecken.',['xBuddy'],'xb-unplug-upper'),
step('センサー・ベッド・アース線を外す|Disconnect sensors, bed and earth|Odpojení senzorů, podložky a PE|Sensoren, Heizbett und PE lösen','ドアセンサーとベッドサーミスターを抜きます。プラスドライバーでヒートベッド出力端子を外します。PE端子はM3×6とワッシャーを外して切り離します。|Unplug the door sensor and bed thermistor. Undo the heatbed output terminal screws. Remove the PE lug with its M3×6 screw and washer.|Odpojte senzor dvířek a termistor podložky. Uvolněte šrouby výstupu pro podložku. PE oko odpojte po vyjmutí M3×6 a podložky.|Türsensor und Heizbett-Thermistor abstecken. Heizbett-Ausgangsklemmen lösen. PE-Ringöse nach Entfernen von M3×6 und Unterlegscheibe abnehmen.',['xBuddy','feGroundRing','feGroundScrew','feGroundWasher'],'xb-unplug-lower'),
step('電源ユニットの配線を外す|Disconnect PSU power leads|Odpojení napájení ze zdroje|Netzteilleitungen lösen','下側の電源入力端子を外します。プラス端子の1か所には、拡張基板からの赤い線も重なっています。外す前に位置を確認します。|Undo the lower PSU input connections. One positive terminal also carries the red extension-board lead; note this stack before removing it.|Odpojte spodní napájecí vstupy ze zdroje. Na jedné kladné svorce je také červený vodič přídavné desky; před rozpojením si sestavu ověřte.|Untere Versorgungseingänge lösen. An einer Plusklemme liegt zusätzlich die rote Leitung der Erweiterungsplatine. Anordnung vor dem Lösen prüfen.',['xBuddy'],'xb-power-out'),
step('Wi-Fiカバーを外す|Remove the Wi-Fi cover|Sejmutí krytu Wi-Fi|Wi-Fi-Abdeckung abnehmen','側面のM3×12を外します。カバーの後ろ側をボックスから浮かせて掛かりを外し、取り外します。|Remove the side M3×12. Lift the rear edge away from the box to release the cover, then remove it.|Vyjměte boční M3×12. Zadní hranu krytu odklopte od boxu, uvolněte zachycení a kryt sejměte.|Seitliche M3×12 entfernen. Hinterkante vom Gehäuse wegkippen, Eingriff lösen und Abdeckung abnehmen.',[169,191],'xb-wifi-cover-out'),
step('Wi-Fiモジュールを外す|Remove the Wi-Fi module|Vyjmutí modulu Wi-Fi|Wi-Fi-Modul ausbauen','モジュールをボックスの側面方向へまっすぐ引き抜きます。|Slide the Wi-Fi module sideways out of its connector.|Modul Wi-Fi vysuňte do strany z konektoru.|Wi-Fi-Modul seitlich gerade aus dem Anschluss ziehen.',['xbWifi'],'xb-wifi-out'),
step('xBuddy基板を外す|Remove the xBuddy board|Vyjmutí desky xBuddy|xBuddy-Platine ausbauen','固定しているM3×6を5本外します。基板の右側を浮かせ、右へ動かして側面の端子を開口から抜きます。ボックス内の古いサーマルパッドを除きます。|Remove the five M3×6 fixing screws. Lift the board’s right edge and move it right to free the side ports. Remove old thermal-pad residue from the box.|Vyjměte pět upevňovacích M3×6. Pravý okraj desky nadzvedněte a posuňte doprava, aby se boční konektory vysunuly z otvorů. Odstraňte zbytky starých podložek.|Fünf M3×6 entfernen. Rechte Platinenseite anheben und nach rechts bewegen, um die seitlichen Anschlüsse freizubekommen. Alte Wärmeleitpadreste aus dem Gehäuse entfernen.',['xBuddy','thermalPads'],'xb-board-out'),
step('交換部品を用意する|Prepare replacement parts|Příprava náhradních dílů|Ersatzteile vorbereiten','新しいxBuddy、サーマルパッド一式、切断した分の結束バンドを用意します。|Prepare the new xBuddy, a thermal-pad set and replacement ties for those removed.|Připravte novou desku xBuddy, sadu teplovodivých podložek a náhradu odstřižených pásek.|Neues xBuddy, Wärmeleitpad-Satz und Ersatz für durchtrennte Kabelbinder bereitlegen.',['xBuddy','thermalPads']),
step('サーマルパッドを貼る|Apply thermal pads|Nalepení teplovodivých podložek|Wärmeleitpads aufbringen','白い保護フィルムをはがし、清潔な基板裏面の指定位置へ貼ります。青い保護フィルムもはがします。基板は縁を持って扱います。|Remove the white liners and apply the pads to the marked areas on the clean rear face. Remove the blue liners too. Hold the board by its edges.|Sejměte bílé fólie a podložky nalepte na určená čistá místa na zadní straně. Sejměte i modré fólie. Desku držte za okraje.|Weiße Schutzfolien abziehen und Pads an den vorgesehenen sauberen Stellen der Rückseite anbringen. Auch blaue Folien entfernen. Platine am Rand halten.',['xBuddy','thermalPads'],'xb-pads'),
step('xBuddy基板を取り付ける|Install the xBuddy board|Montáž desky xBuddy|xBuddy-Platine einsetzen','左側の銀色の端子を先に開口へ入れ、基板をボックス側へ倒します。配線を挟まず、M3×6を5本締めます。右下のPE用の穴は空けておきます。|Engage the silver left-side ports first, then lean the board into the box. Keep wires clear and fit five M3×6 screws. Leave the lower-right PE hole empty.|Nejprve zasuňte stříbrné levé konektory do otvorů a desku přiklopte do boxu. Neskřípněte kabely, upevněte pět M3×6 a pravý dolní otvor PE nechte volný.|Zuerst silberne Anschlüsse links einfädeln, dann Platine ins Gehäuse klappen. Kabel freihalten und fünf M3×6 einsetzen. PE-Bohrung unten rechts frei lassen.',['xBuddy','thermalPads'],'xb-board-in'),
step('Wi-Fiモジュールを戻す|Refit the Wi-Fi module|Montáž modulu Wi-Fi|Wi-Fi-Modul einsetzen','モジュールを側面の端子へ差し込みます。端子がずれていないことを確認します。|Slide the module into the side connector and check its alignment.|Modul zasuňte do bočního konektoru a ověřte jeho vyrovnání.|Modul in den seitlichen Anschluss schieben und Ausrichtung prüfen.',['xbWifi'],'xb-wifi-in'),
step('Wi-Fiカバーを戻す|Refit the Wi-Fi cover|Montáž krytu Wi-Fi|Wi-Fi-Abdeckung montieren','斜めにしてモジュールの端へ掛け、後ろ側をボックスへ閉じます。M3×12で固定します。|Hook the cover over the module’s edge at an angle, close its rear edge toward the box and secure with M3×12.|Kryt šikmo zachyťte za hranu modulu, zadní část přiklopte k boxu a zajistěte M3×12.|Abdeckung schräg am Modulrand einhaken, hinten zum Gehäuse schließen und mit M3×12 sichern.',[169,191],'xb-wifi-cover-in'),
step('HEATBED INに電源を接続する|Connect PSU to HEATBED IN|Napájení vstupu HEATBED IN|Netzteil an HEATBED IN anschließen','写真左側のHEATBED INへ、赤を＋、黒を−に接続して端子ネジを締めます。右隣のPOWER INとは区別します。|At the left lower pair marked HEATBED IN, connect red to + and black to − and tighten the screws. POWER IN is the separate pair to its right.|Na levé spodní dvojici HEATBED IN připojte červený na + a černý na −, šrouby dotáhněte. POWER IN je samostatná dvojice vpravo.|Am unteren linken Paar HEATBED IN Rot an + und Schwarz an − anschließen und Schrauben anziehen. POWER IN liegt separat rechts daneben.',['xbHeatInPlus','xbHeatInMinus'],'xb-heat-in'),
step('ボックスに結束バンドを通す|Prepare the box ties|Příprava pásek v boxu|Kabelbinder im Gehäuse vorbereiten','ボックス右側の取り付け穴へ通します。後で締められるよう、ロック部は外向き、先端は基板の上へ出します。まだ締めません。|Thread ties through the right-side attachment points. Face the heads outward and leave tails above the board for access. Leave them loose.|Pásky provlékněte úchyty na pravé straně. Hlavičky orientujte ven a konce nechte nad deskou. Zatím je neutahujte.|Durch die rechten Befestigungen fädeln. Köpfe nach außen, Enden über der Platine zugänglich lassen. Noch nicht festziehen.',['box1','box2','box4','box5'],'xb-ties-in'),
step('拡張基板をMMUへ接続する|Connect the extension board to MMU|Propojení přídavné desky s MMU|Erweiterungsplatine mit MMU verbinden','短いケーブルをxBuddy上段のMMUへ接続します。追加の赤い線がある側を拡張基板の右側端子へつなぎ、その赤い線を電源端子へ下ろします。|Connect the short cable to the upper MMU port. Its end with extra red wires belongs at the extension board’s right connector. Route those red wires down to the power terminals.|Krátký kabel připojte k hornímu MMU. Konec s přídavnými červenými vodiči patří do pravého konektoru přídavné desky; vodiče veďte dolů ke svorkám.|Kurzes Kabel oben an MMU anschließen. Ende mit zusätzlichen roten Leitungen an den rechten Anschluss der Erweiterungsplatine setzen. Rote Leitungen nach unten zu den Klemmen führen.',['xbMmu','xbExtensionEnd'],'xb-mmu-in'),
step('POWER INに電源と赤い線を接続する|Connect POWER IN and the extra red lead|Připojení POWER IN a červeného vodiče|POWER IN und zusätzliche rote Leitung anschließen','POWER INの＋へ、PSUの赤と拡張基板の赤い線を重ねます。PSUの黒は−へ接続します。PEはまだ接続せず、カバーのネジ穴を避けて配線してから締めます。|Stack the PSU red lug and extension red lead at POWER IN +. Connect PSU black to −. Leave PE disconnected and keep the cover’s threaded hole clear before tightening.|Na POWER IN + složte červené oko zdroje a červený vodič přídavné desky. Černý připojte na −. PE zatím nepřipojujte a před dotažením uvolněte prostor u otvoru pro kryt.|Rote Netzteil-Ringöse und rote Erweiterungsleitung an POWER IN + übereinanderlegen. Schwarz an −. PE noch offen lassen und Gewindebohrung für die Abdeckung vor dem Festziehen freihalten.',['xbPowerPlus','xbPowerMinus','xbExtensionRed'],'xb-power-in'),
step('PEアース線を固定する|Secure the PE earth lug|Upevnění ochranného vodiče PE|PE-Ringöse befestigen','右下のPE用の穴へ丸端子を合わせ、端子の上にワッシャーを置き、M3×6で固定します。|Place the earth lug over the lower-right PE hole. Put the washer above the lug and secure with M3×6.|Oko PE přiložte k pravému dolnímu otvoru. Podložku dejte nad oko a zajistěte M3×6.|PE-Ringöse über die Bohrung unten rechts legen. Unterlegscheibe auf die Ringöse setzen und mit M3×6 befestigen.',['feGroundRing','feGroundWasher','feGroundScrew'],'xb-pe-in'),
step('Power PanicとZモーターを接続する|Connect Power Panic and Z motors|Připojení Power Panic a motorů Z|Power Panic und Z-Motoren anschließen','Power Panicを右下の端子へ差し、余りを側面へ沿わせます。Zモーター配線を下から上へ通し、ZLへ接続します。ZRも並列接続されているため使用できます。|Connect Power Panic at the lower right and route its slack along the side. Bring the Z-motor cable up from below to ZL; the parallel ZR port is also valid.|Power Panic připojte vpravo dole a přebytek veďte po straně. Kabel motorů Z veďte zdola do ZL; použít lze i paralelně zapojený ZR.|Power Panic unten rechts einstecken und Rest seitlich führen. Z-Motorkabel von unten zu ZL führen; der parallel geschaltete ZR ist ebenfalls geeignet.',['xbPanic','splitterZRPlug'],'xb-z-panic-in'),
step('メインとxLCDを接続する|Connect main cable and xLCD|Připojení hlavního kabelu a xLCD|Hauptkabel und xLCD anschließen','Nextruderメインを上から側面へ沿わせて接続します。xLCDは下から通し、端子の切り欠きを基板の三角印へ向けます。一番下の結束バンドを軽く締め、余りを切ります。|Route the Nextruder main cable down the side. Bring xLCD up from below with its connector notch facing the board’s triangle. Close the lowest tie without overtightening and trim its tail.|Hlavní kabel Nextruderu veďte shora po straně. xLCD veďte zdola, výřez konektoru směrem k trojúhelníku na desce. Spodní pásku lehce utáhněte a odstřihněte konec.|Nextruder-Hauptkabel von oben seitlich führen. xLCD von unten führen; Steckeraussparung zum Dreieck auf der Platine ausrichten. Untersten Kabelbinder maßvoll schließen und Ende kürzen.',['xbMain','xbLcd','box5'],'xb-main-lcd-in'),
step('サーミスターとドアセンサーを接続する|Connect thermistor and door sensor|Připojení termistoru a senzoru dvířek|Thermistor und Türsensor anschließen','緑のHラベルの線をヒートベッド電源端子横のBED TEMPへ接続します。白・茶の線が入った黒いドアセンサー配線をA_TEMPへ接続します。|Connect the green H-tagged thermistor lead to BED TEMP beside the bed power terminals. Connect the black-sleeved white/brown door lead to A_TEMP.|Termistor se zeleným štítkem H připojte do BED TEMP vedle výkonových svorek podložky. Černý kabel dvířek s bílým a hnědým vodičem patří do A_TEMP.|Thermistorleitung mit grünem H-Etikett an BED TEMP neben den Heizbettklemmen stecken. Schwarz ummantelte Türsensorleitung mit weißer/brauner Ader an A_TEMP anschließen.',['xbBedTemp','xbDoor'],'xb-sensors-in'),
step('X・Yモーターを接続する|Connect X and Y motors|Připojení motorů X a Y|X- und Y-Motoren anschließen','Xを上段の1番目、Yを2番目の端子へ接続します。準備した結束バンドで右側の配線束を固定し、余りを切ります。|Connect X to the first upper socket and Y to the second. Secure the side bundle with the prepared ties and trim the tails.|X zapojte do prvního horního konektoru, Y do druhého. Svazek po straně zajistěte připravenými páskami a konce odstřihněte.|X in den ersten, Y in den zweiten oberen Anschluss stecken. Seitliches Bündel mit vorbereiteten Kabelbindern sichern und Enden kürzen.',['xbX','xbY','box1','box2','box4'],'xb-xy-in'),
step('ヒートベッド出力を接続する|Connect the heatbed output|Připojení výstupu pro podložku|Heizbett-Ausgang anschließen','上から来るヒートベッド電源線をHEATBED OUTへ接続します。黒は−、赤は＋です。それぞれ端子ネジで確実に固定します。|Connect the heatbed leads arriving from above to HEATBED OUT: black to −, red to +. Tighten both terminal screws.|Kabely podložky přicházející shora připojte na HEATBED OUT: černý na −, červený na +. Oba šrouby řádně dotáhněte.|Von oben kommende Heizbettleitungen an HEATBED OUT anschließen: Schwarz an −, Rot an +. Beide Klemmschrauben festziehen.',['xbBedMinus','xbBedPlus'],'xb-bed-out-in'),
step('配線を照合する|Check the wiring|Kontrola zapojení|Verdrahtung prüfen','カバーを閉じる前に公式の接続図と照合します。モーター、MMU、xLCD、メイン、センサー、電源の極性、PEを一つずつ確認します。|Before closing, compare every connection with the official diagram: motors, MMU, xLCD, main, sensors, power polarity and PE.|Před zavřením porovnejte všechny spoje s oficiálním schématem: motory, MMU, xLCD, hlavní kabel, senzory, polaritu i PE.|Vor dem Schließen alle Anschlüsse mit dem offiziellen Schema vergleichen: Motoren, MMU, xLCD, Hauptkabel, Sensoren, Polarität und PE.',['xBuddy'],'xb-wiring-check'),
step('NFCとxBuddyカバーを戻す|Restore NFC and the xBuddy cover|Obnovení NFC a krytu xBuddy|NFC und xBuddy-Abdeckung wieder montieren','先にNFC端子と下カバーを元へ戻し、ケーブルをEthernet端子とPSU配線の間へ通します。金属カバーの曲がった側を先に入れ、配線を挟まずネジ6本で固定します。NFCの復旧は下記の公式組み立て手順も参照します。|First restore the NFC connection and lower cover; route its lead between Ethernet and PSU cables. Insert the metal cover’s bent edge first and secure all six screws without trapping wires. Use the linked official assembly steps for NFC restoration.|Nejprve obnovte NFC a spodní kryt; kabel veďte mezi Ethernetem a napájecími vodiči. Zahnutou hranu kovového krytu vložte první a upevněte šest šroubů bez skřípnutí kabelů. Pro NFC použijte připojené oficiální montážní kroky.|Zuerst NFC und untere Abdeckung wiederherstellen; Leitung zwischen Ethernet und Netzteilleitungen führen. Gebogene Metallkante zuerst einsetzen und sechs Schrauben ohne eingeklemmte Kabel befestigen. Für NFC die verlinkten offiziellen Montageschritte nutzen.',[206,240,'xbNfcPlug'],'xb-box-in',{supplementalSources:[{url:'https://help.prusa3d.com/guide/7-bodywork-electronics_982292#996903',label:l('NFC端子の接続（公式）|Connect NFC — official assembly|Zapojení NFC — oficiální montáž|NFC anschließen — offizielle Montage')},{url:'https://help.prusa3d.com/guide/7-bodywork-electronics_982292#996979',label:l('NFC下カバーと配線（公式）|NFC cover and cable route — official|Kryt NFC a vedení kabelu — oficiální|NFC-Abdeckung und Leitungsweg — offiziell')}] }),
step('背面カバーを戻す|Refit the rear cover|Montáž zadního krytu|Rückabdeckung montieren','配線を挟まない位置へ戻し、カバーを上へ押してフック4か所を掛けます。押し上げたまま内側からネジ2本で固定します。|Clear the wires and slide the rear cover up to engage all four hooks. Hold it up while fitting the two screws from inside.|Uvolněte kabely a kryt posuňte nahoru, až zapadnou všechny čtyři háčky. Držte jej nahoře a zevnitř upevněte oba šrouby.|Kabel freihalten und Abdeckung hochschieben, bis alle vier Haken greifen. Hochgedrückt halten und beide Schrauben von innen einsetzen.',[78],'xb-rear-in'),
step('電源を入れてテストする|Power on and test|Zapnutí a testy|Einschalten und testen','電源コードを接続して電源を入れ、ドアを閉じます。Control → Calibration & Testsからテストを実行し、動作を確認します。|Reconnect power, switch on and close the door. Run the checks under Control → Calibration & Tests.|Připojte napájení, tiskárnu zapněte a zavřete dvířka. Proveďte testy v Control → Calibration & Tests.|Netzkabel anschließen, einschalten und Tür schließen. Tests unter Control → Calibration & Tests ausführen.',['lcd','psu'])
]};
XBUDDY_TASK.pdf=XBUDDY_SOURCE.pdf;
XBUDDY_TASK.steps.forEach((s,i)=>{s.number=i+1;s.page=XBUDDY_SOURCE.steps[i].pdfPage;});
